import{_ as i,o,c as a,ap as t}from"./chunks/framework.CuFS6FqL.js";const m=JSON.parse('{"title":"📝 Information Security Policy","description":"Policy defining how Syslifters protects information and customer data.","frontmatter":{"title":"📝 Information Security Policy","description":"Policy defining how Syslifters protects information and customer data."},"headers":[],"relativePath":"organization/information-security-policy.md","filePath":"organization/information-security-policy.md"}'),r={name:"organization/information-security-policy.md"};function n(s,e,l,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/information-security-policy.md for this page in Markdown format</div><h1 id="📝-information-security-policy" tabindex="-1">📝 Information Security Policy <a class="header-anchor" href="#📝-information-security-policy" aria-label="Permalink to &quot;📝 Information Security Policy&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This policy sets the requirements for protecting the confidentiality, integrity, and availability of Syslifters and customer information, and for meeting applicable law (primarily GDPR, as an Austrian controller).</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This policy applies to all employees, contractors, and third parties who access or manage our information systems, networks, or data, whether stored digitally or physically.</p><h2 id="information-protection-principles" tabindex="-1">Information Protection Principles <a class="header-anchor" href="#information-protection-principles" aria-label="Permalink to &quot;Information Protection Principles&quot;">​</a></h2><ul><li><strong>Confidentiality.</strong> Personal and sensitive data must be protected from unauthorized access, disclosure, or misuse.</li><li><strong>Integrity.</strong> Information must be accurate, complete, and protected from unauthorized modification or destruction.</li><li><strong>Availability.</strong> Information and systems must be accessible to authorized users as needed for business operations.</li></ul><h2 id="customer-data-handling" tabindex="-1">Customer data handling <a class="header-anchor" href="#customer-data-handling" aria-label="Permalink to &quot;Customer data handling&quot;">​</a></h2><ul><li>Use only company-issued devices for Syslifters and customer work. Private use of those devices is not allowed.</li><li>Use Signal with disappearing messages for internal and project communication.</li><li>Do not put customer data into cloud AI unless the customer has explicitly allowed it. Use our self-hosted models (e.g., <code>local_model_default</code>) as the default.</li></ul><h2 id="personal-information-protection" tabindex="-1">Personal Information Protection <a class="header-anchor" href="#personal-information-protection" aria-label="Permalink to &quot;Personal Information Protection&quot;">​</a></h2><ul><li>Collect, store, process, and transmit personal data only for a legitimate business purpose and in line with GDPR and other applicable law.</li><li>Keep only what is needed, and only for as long as it is needed.</li><li>We maintain our privacy policies and registers at <a href="https://hub.metasoul.com/" target="_blank" rel="noreferrer">Metasoul</a>. Website processing is described in the <a href="/privacy">Privacy notice</a>.</li><li>Report any suspected or confirmed security or privacy incident immediately, following our <a href="/organization/incident-response">incident response procedures</a>.</li></ul><h2 id="responsibilities" tabindex="-1">Responsibilities <a class="header-anchor" href="#responsibilities" aria-label="Permalink to &quot;Responsibilities&quot;">​</a></h2><p>All employees must follow this policy and complete periodic information security and privacy training. Management oversees compliance, monitors controls, and updates the policy as needed.</p><p>Exceptions to this policy need written approval from a director before the work proceeds.</p><h2 id="policy-review" tabindex="-1">Policy Review <a class="header-anchor" href="#policy-review" aria-label="Permalink to &quot;Policy Review&quot;">​</a></h2><p>This policy will be reviewed annually or following significant organizational or regulatory changes.</p><p>Last reviewed: 03/09/2026</p>',18)])])}const h=i(r,[["render",n]]);export{m as __pageData,h as default};
